<script setup>
import { useVehicleRealtime } from '../composables/useVehicleRealtime'
import { computed, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { shopService } from '../services/shopService'
import { useResource } from '../composables/useResource'
import { shopMedia } from '../utils/demoMedia'
import { locationLabel } from '../utils/format'
import VehicleCard from '../components/VehicleCard.vue'
import SafeImage from '../components/SafeImage.vue'
import ResultState from '../components/ResultState.vue'
import PaginationNav from '../components/PaginationNav.vue'
import FutureAction from '../components/FutureAction.vue'
import LocationPanel from '../components/LocationPanel.vue'
const route = useRoute(), router = useRouter(), profile = useResource(), inventory = useResource()
const { newListings, refresh } = useVehicleRealtime(inventory.data, loadInventory, { shopId: () => shop.value?.id, needsReconcile: fields => tab.value === 'available' ? fields.includes('inventory_status') : tab.value !== 'all' && fields.some(f => ['is_for_sale','is_for_rent'].includes(f)) })
const shop = computed(() => profile.data.value?.data)
const tab = computed(() => ['sale', 'rental', 'available'].includes(route.query.tab) ? route.query.tab : 'all')
const tabs = { all: 'Tous', sale: 'À vendre', rental: 'À louer', available: 'Disponibles' }
function params() { return { page: route.query.page || 1, per_page: 12, ...(tab.value === 'available' ? { status: 'available' } : tab.value !== 'all' ? { listing_type: tab.value } : {}) } }
function loadInventory() { inventory.load(signal => shopService.vehicles(route.params.slug, params(), signal)) }
async function reload() { await profile.load(signal => shopService.detail(route.params.slug, signal)); if (shop.value) document.title = `${shop.value.name} | BolideMarket` }
function navigate(value, page = 1) { router.push({ path: route.path, query: { ...(value !== 'all' ? { tab: value } : {}), ...(page !== 1 ? { page } : {}) } }) }
watch(() => route.params.slug, reload, { immediate: true })
watch(() => [route.params.slug, route.query.tab, route.query.page], loadInventory, { immediate: true })
const contact = computed(() => shop.value?.is_demo ? null : { phone: /^\+?[\d\s()-]+$/.test(shop.value?.phone || '') ? shop.value.phone.replace(/[^+\d]/g, '') : '', email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(shop.value?.email || '') ? shop.value.email : '' })
</script>
<template><div class="container page-content"><nav class="breadcrumbs" aria-label="Fil d’Ariane"><RouterLink to="/shops">Professionnels</RouterLink><span>/</span><span>{{ shop?.name || 'Boutique' }}</span></nav><ResultState :state="profile.state.value" :error="profile.error.value" @retry="reload"><template v-if="shop"><section class="shop-hero"><div class="shop-cover"><SafeImage :src="shopMedia(shop)" :alt="`Présentation de ${shop.name}`" eager /><span v-if="shop.is_demo && !shop.cover_url && shopMedia(shop)" class="photo-note">Illustration de démonstration</span></div><div class="shop-identity"><span class="avatar shop-avatar"><SafeImage v-if="shop.logo_url" :src="shop.logo_url" :alt="shop.name" style="width:100%;height:100%;object-fit:contain;border-radius:inherit"/><template v-else>{{ shop.name.split(' ').slice(0, 2).map(x => x[0]).join('') }}</template></span><div><p class="eyebrow">BOUTIQUE PROFESSIONNELLE</p><h1>{{ shop.name }}</h1><p>{{ locationLabel(shop.location) }}</p><p v-if="shop.sale_vehicles_count || shop.rental_vehicles_count">{{ shop.sale_vehicles_count && shop.rental_vehicles_count ? 'Vente & Location' : shop.sale_vehicles_count ? 'Vente' : 'Location' }}</p><span v-if="shop.merchant?.is_verified" class="pill">Professionnel vérifié</span></div><div class="shop-count"><strong>{{ shop.published_vehicles_count }}</strong><span>véhicules publiés</span></div></div></section><div class="shop-layout"><aside class="shop-about content-panel"><h2>Bienvenue chez nous</h2><p class="description">{{ shop.description || 'Découvrez le parc de ce professionnel.' }}</p><template v-if="shop.opening_hours?.length"><h3>Horaires</h3><p v-for="day in shop.opening_hours" :key="day.day">{{ ['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'][day.day-1] }} : {{ day.closed ? 'Fermé' : day.opens + ' – ' + day.closes }}</p></template><h3>Nous trouver</h3><p>{{ shop.address }}</p><p>{{ locationLabel(shop.location) }}</p><template v-if="contact"><a v-if="contact.phone" class="button secondary full" :href="`tel:${contact.phone}`">{{ shop.phone }}</a><a v-if="contact.email" class="contact-email" :href="`mailto:${contact.email}`">{{ shop.email }}</a></template><FutureAction v-else label="Contacter la boutique" /><p v-if="shop.is_demo" class="demo-note">{{ shop.demo_notice }} Les coordonnées démo ne permettent pas de contacter un vendeur réel.</p></aside><section class="shop-inventory" aria-label="Parc de la boutique"><div class="section-heading"><h2>Notre sélection</h2><span>{{ inventory.data.value?.meta?.total ?? '—' }} offres</span></div><p v-if="newListings" role="status" class="notice">De nouvelles annonces sont disponibles. <button class="text-button" @click="refresh">Actualiser</button></p><nav class="offer-tabs" aria-label="Offres de la boutique"><button v-for="(label, value) in tabs" :key="value" :aria-pressed="tab === value" @click="navigate(value)">{{ label }}</button></nav><ResultState :state="inventory.state.value" :error="inventory.error.value" :empty="!inventory.data.value?.data?.length" @retry="loadInventory" @reset="navigate('all')"><div class="vehicle-grid"><VehicleCard v-for="item in inventory.data.value.data" :key="item.id" :vehicle="item" :intention="tab === 'rental' ? 'rental' : tab === 'sale' ? 'sale' : undefined" /></div><PaginationNav :meta="inventory.data.value.meta" @change="navigate(tab, $event)" /></ResultState></section></div><LocationPanel :location="shop.location" :address="shop.address" /></template></ResultState></div></template>
